            (lock_ba, ()),   # B→A locks B
            (do_ab, ()),     # A→B tries to lock B — DEADLOCK
            (do_ba, ()),     # never reached
        ])
        return get_state()
    except RuntimeError as e:
        return {"error": str(e)}
